def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--paragraphs", required=True)
    parser.add_argument("--links", required=True)
    parser.add_argument("--style", required=True)
    parser.add_argument("--pr", required=True)
    parser.add_argument("--repo", default="https://github.com/kubernetes/website")
    parser.add_argument(
        "--head-repo",
        default="",
        help="PR head repository URL used for Spanish file references",
    )
    parser.add_argument(
        "--head-ref",
        default="",
        help="PR head git ref (typically commit SHA) for Spanish file references",
    )
    parser.add_argument("--out", required=True)
    parser.add_argument(
        "--comment-out",
        default=None,
        metavar="PATH",
        help="Optional path for a compact PR comment Markdown artifact",
    )
    parser.add_argument(
        "--base-findings",
        default=None,
        metavar="PATH",
        help="JSON findings from a previous review for follow-up comparison",
    )
    args = parser.parse_args()

    para_data = load_json(args.paragraphs)
    link_data = load_json(args.links)
    style_data = load_json(args.style)

    all_findings = (
        para_data.get("findings", [])
        + link_data.get("findings", [])
        + style_data.get("findings", [])
    )
    display_findings = compress_findings_for_display(all_findings)
    all_errors = (
        para_data.get("errors", [])
        + link_data.get("errors", [])
        + style_data.get("errors", [])
    )

    by_file = group_by_file(display_findings)
    total_counts = severity_counts(display_findings)
    files_reviewed = sorted(by_file.keys()) or ["(ninguno)"]

    # Follow-up comparison if base findings provided
    followup_section = ""
    if args.base_findings:
        try:
            base_data = json.loads(Path(args.base_findings).read_text())
            base_findings = base_data.get("findings", [])
            resolved, pending, new_findings = compare_with_base(
                display_findings, compress_findings_for_display(base_findings)
            )
            followup_section = render_followup_section(
                resolved,
                pending,
                new_findings,
                args.repo,
                args.pr,
                head_repo=args.head_repo,
                head_ref=args.head_ref,
            )
        except Exception as exc:
            followup_section = (
                f"\n> **Advertencia:** No se pudo cargar el archivo de base: {exc}\n"
            )

    is_followup = bool(followup_section)

    pr_url = f"{args.repo.rstrip('/')}/pull/{args.pr}"
    mode_label = "Seguimiento" if is_followup else "Revisi\u00f3n"

    mode_str = "Seguimiento (con base de revisión anterior)" if is_followup else "Primera revisión"
    lines = [
        f"# {mode_label} de PR #{args.pr} \u2014 Documentaci\u00f3n Kubernetes en Espa\u00f1ol",
        "",
        f"> **PR:** [{pr_url}]({pr_url})  ",
        f"> **Fecha:** {date.today()}  ",
        f"> **Archivos revisados:** {len(files_reviewed)}  ",
        f"> **Modo:** {mode_str}  ",
        "> **Herramienta:** k8s-es-translation-review  ",
        "",
        "---",
        "",
    ]

    if followup_section:
        lines.append(followup_section)

    lines += [
        render_summary_checklist(total_counts, files_reviewed),
        render_enumerated_observations(display_findings),
        render_k8s_contrib_checklist(files_reviewed),
    ]

    if all_errors:
        lines.append(render_error_section(all_errors))

    lines += [
        "---",
        "",
        "## Observaciones por archivo",
        "",
    ]

    if not by_file:
        lines.append(
            "_No se encontraron observaciones. El PR cumple con los criterios de revisión._ ✅\n"
        )
    else:
        for file_path in sorted(by_file.keys()):
            file_findings = by_file[file_path]
            fc = severity_counts(file_findings)
            badge = ""
            if fc["error"]:
                badge = f" — {fc['error']} 🔴"
            elif fc["warning"]:
                badge = f" — {fc['warning']} 🟡"
            else:
                badge = f" — {fc['suggestion']} 🔵"
            if file_path.startswith("content/es/"):
                blob_url = build_blob_url(
                    args.head_repo or args.repo,
                    file_path,
                    ref=args.head_ref or "main",
                )
            else:
                blob_url = build_blob_url(args.repo, file_path, ref="main")
            lines += [
                f"### [`{file_path}`]({blob_url}){badge}",
                "",
                render_table(
                    file_findings,
                    args.repo,
                    args.pr,
                    head_repo=args.head_repo,
                    head_ref=args.head_ref,
                ),
                "",
            ]

    lines += [
        "---",
        "",
        "## Códigos de revisión",
        "",
        "| Código | Descripción |",
        "|--------|-------------|",
        "| PARA-001 | Frontmatter incompleto (campo faltante) |",
        "| PARA-002 | Marcador de conflicto de merge sin resolver |",
        "| PARA-003 | Sección con muy poco contenido respecto al original |",
        "| PARA-004 | Sección h2 del original EN ausente en la traducción |",
        "| PARA-005 | Sección h2 extra en ES sin equivalente EN |",
        "| PARA-006 | Archivo ES huérfano (sin fuente EN) |",
        "| PARA-007 | Compresión de saltos de línea semánticos: ES tiene significativamente menos líneas de prosa que EN |",
        "| LINK-001 | Enlace interno roto |",
        "| LINK-002 | Enlace a ruta ES inexistente (sí existe en EN) |",
        "| LINK-003 | Ancla `#id` no encontrada en archivo destino |",
        "| STYLE-001 | Fragmento en inglés sin traducir (4+ palabras) |",
        "| STYLE-002 | Inconsistencia de registro (tú vs usted) |",
        "| STYLE-003x | Terminología inconsistente |",
        "| STYLE-004x | Error tipográfico (doble espacio, tilde faltante) |",
        "| STYLE-007 | Compresión EN(2 líneas) → ES(1 línea) que puede desalinear contexto |",
        "| STYLE-005 | Comando de kubectl/kubeadm modificado en bloque de código |",
        "",
        "_Generado por [k8s-docs-es-review](https://github.com/kubernetes/website)_",
    ]

    out_path = Path(args.out)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text("\n".join(lines), encoding="utf-8")
    if args.comment_out:
        comment_path = Path(args.comment_out)
        comment_path.parent.mkdir(parents=True, exist_ok=True)
        comment_path.write_text(
            render_compact_comment(display_findings, args.pr), encoding="utf-8"
        )
        print(
            f"generate_report: compact comment written to {comment_path} ({comment_path.stat().st_size} bytes)"
        )
    print(
        f"generate_report: report written to {out_path} ({out_path.stat().st_size} bytes)"
    )


if __name__ == "__main__":
    main()
